{
  "implementation": "import math

def solve(case):
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    n = len(sentence_vectors)
    # compute cosine similarities
    own_sims = []
    norm_q = math.sqrt(sum(x*x for x in query_vector))
    for vec in sentence_vectors:
        norm_v = math.sqrt(sum(x*x for x in vec))
        if norm_v == 0 or norm_q == 0:
            sim = 0.0
        else:
            dot = sum(a*b for a,b in zip(vec, query_vector))
            sim = dot / (norm_v * norm_q)
        own_sims.append(sim)
    # compute neighbor averaged similarities
    neighbor_avgs = []
    for i in range(n):
        if n == 1:
            avg = 0.0
        elif i == 0:
            avg = own_sims[1]
        elif i == n-1:
            avg = own_sims[n-2]
        else:
            avg = (own_sims[i-1] + own_sims[i+1]) / 2.0
        neighbor_avgs.append(avg)
    # blend scores
    scores = []
    for i in range(n):
        blended = (1 - context_weight) * own_sims[i] + context_weight * neighbor_avgs[i]
        scores.append(round(blended, 4))
    # sort by descending score, then ascending index
    indexed = [(scores[i], i) for i in range(n)]
    indexed.sort(key=lambda x: (-x[0], x[1]))
    ranking = [idx for _, idx in indexed]
    sorted_scores = [score for score, _ in indexed]
    return {"ranking": ranking, "scores": sorted_scores}
